  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ────────────────────────────────────────────────────────────────────\n\nenum Role {\n  STUDENT\n  COMPANY\n  COLLEGE\n  ADMIN\n}\n\nenum JobType {\n  INTERNSHIP\n  JOB\n}\n\nenum AppStatus {\n  APPLIED\n  SHORTLISTED\n  ACCEPTED\n  REJECTED\n}\n\nenum VerificationStatus {\n  PENDING\n  VERIFIED\n  REJECTED\n}\n\n// ─── Core User ────────────────────────────────────────────────────────────────\n\nmodel User {\n  id        String   @id @default(cuid())\n  name      String\n  email     String   @unique\n  password  String\n  role      Role     @default(STUDENT)\n  isActive  Boolean  @default(false) // colleges must verify students before activation\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  student StudentProfile?\n  company Company?\n  college College?\n}\n\n// ─── Student ──────────────────────────────────────────────────────────────────\n\nmodel StudentProfile {\n  id             String  @id @default(cuid())\n  userId         String  @unique\n  user           User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  institution    String\n  degree         String // BAMS, BHMS, BUMS, BNYS, B.Sc Yoga, BSMS, DHMS etc.\n  graduationYear Int\n  city           String\n  state          String  @default(\"\")\n  resumeUrl      String?\n  photoUrl       String?\n  linkedinUrl    String?\n  achievements   String?\n  bio            String?\n\n  skills       StudentSkill[]\n  applications Application[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel StudentSkill {\n  studentId String\n  skillId   String\n  student   StudentProfile @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  skill     Skill          @relation(fields: [skillId], references: [id], onDelete: Cascade)\n\n  @@id([studentId, skillId])\n}\n\n// ─── Skill Taxonomy ───────────────────────────────────────────────────────────\n\nmodel Skill {\n  id     String @id @default(cuid())\n  name   String @unique\n  system String // Ayurveda | Yoga & Naturopathy | Unani | Siddha | Homeopathy | Research & Clinical\n\n  students StudentSkill[]\n  jobs     JobSkill[]\n}\n\n// ─── Company ──────────────────────────────────────────────────────────────────\n\nmodel Company {\n  id          String  @id @default(cuid())\n  userId      String  @unique\n  user        User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name        String\n  sector      String // Ayurveda pharma, Wellness chain, Hospital, Research, etc.\n  website     String?\n  city        String?\n  description String?\n  logoUrl     String?\n\n  jobs JobListing[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─── College ──────────────────────────────────────────────────────────────────\n\nmodel College {\n  id                 String             @id @default(cuid())\n  userId             String             @unique\n  user               User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name               String\n  city               String\n  state              String\n  affiliation        String? // University or autonomous\n  verificationStatus VerificationStatus @default(PENDING)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─── Job Listings ─────────────────────────────────────────────────────────────\n\nmodel JobListing {\n  id          String   @id @default(cuid())\n  companyId   String\n  company     Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  title       String\n  description String\n  type        JobType\n  location    String\n  stipend     String?\n  deadline    DateTime\n  isActive    Boolean  @default(true)\n\n  skills       JobSkill[]\n  applications Application[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel JobSkill {\n  jobId   String\n  skillId String\n  job     JobListing @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  skill   Skill      @relation(fields: [skillId], references: [id], onDelete: Cascade)\n\n  @@id([jobId, skillId])\n}\n\n// ─── Applications ─────────────────────────────────────────────────────────────\n\nmodel Application {\n  id        String    @id @default(cuid())\n  studentId String\n  jobId     String\n  status    AppStatus @default(APPLIED)\n  note      String? // company's note on the applicant\n\n  student StudentProfile @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  job     JobListing     @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  appliedAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([studentId, jobId]) // prevent duplicate applications\n}\n",
